class Solution {
public:
    int numSquares(int n) {
        // Case 1: n is a perfect square
        int root = (int)sqrt((double)n);
        if (root * root == n) return 1;

        // Case 4: n has the form 4^a * (8b + 7) by Legendre's three-square theorem
        int m = n;
        while (m % 4 == 0) {
            m /= 4;
        }
        if (m % 8 == 7) return 4;

        // Case 2: n is a sum of two perfect squares
        for (int i = 1; i * i <= n; i++) {
            int rem = n - i * i;
            int r = (int)sqrt((double)rem);
            if (r * r == rem) return 2;
        }

        // Case 3: otherwise, n is a sum of three squares
        return 3;
    }
};
